sharpened.graph_schema:
// jaclang 0.16.x — same syntax family as our working money_graph.jac
// Verify typed-edge operator (+>:Type(...):+> vs ++>:Type:...) in the first 30 min.

node Registry {                    // singleton under root: the lives-saved counter + demo state
    has lives_saved: int = 0;
    has lives_at_risk: int = 0;
    has phase: str = "idle";       // drives frontend animation state
}

node Hospital {
    has name: str;                 // "UCSF", "Stanford", "CPMC", "Zuckerberg SF General"
    has color: str;                // cluster color for cytoscape
}

node Pair {                        // one incompatible donor+patient couple
    has pair_id: str;              // "P07"
    has patient_name: str;
    has patient_blood: str;        // "O" | "A" | "B" | "AB"
    has donor_name: str;
    has donor_blood: str;
    has urgency: int;              // 1-10, used by policy + arbiter
    has wait_months: int;
    has status: str = "waiting";   // waiting | in_chain | transplanted | stranded | withdrawn
}

node AltruisticDonor {
    has name: str;
    has blood: str;
    has hospital: str;
    has note_excerpt: str;         // quote from the parsed referral email
    has status: str = "available"; // available | committed | withdrawn
}

node Chain {                       // a candidate/approved swap chain — minted BY the ChainSeeker walker
    has chain_id: str;             // "C1"
    has hop_ids: list;             // ordered pair_ids, e.g. ["ALT","P03","P11","P07","P22","P14"]
    has kind: str;                 // "altruist" (open chain) | "cycle" (2-3 way swap)
    has lives: int;                // len of hops that get a kidney
    has status: str = "proposed";  // proposed | approved | rejected | executed | broken
    has narration: str = "";       // explain_chain() output
    has rationale: str = "";       // arbiter's reason if approved/rejected
}

node Docket {                      // holds the advocate cases + policy for one arbitration round
    has policy_text: str;          // the written ethics policy, shown verbatim on screen
    has cases: list = [];          // serialized Case objects
}

// ---- edges ----
edge AtHospital {}                       // Pair --> Hospital
edge CanGive { has score: float; }       // donor of Pair A (or AltruisticDonor) --> Pair B whose
                                         // patient can receive; score = blood match + synthetic HLA jitter.
                                         // Laid down by CompatibilityWeaver. THIS is the digraph the DFS runs on.
edge InChain { has position: int; }      // Pair --> Chain (membership + hop order)
edge Starts {}                           // AltruisticDonor --> Chain

// Blood compatibility is a plain dict, not LLM: O->all, A->{A,AB}, B->{B,AB}, AB->{AB}.
// Dataset is HAND-SEEDED (gen_data.jac) so exactly these exist: one 6-hop altruist chain,
// two overlapping alternatives sharing P12, one 3-cycle, and a 4-hop rescue path that
// survives removal of the pair whose donor withdraws. Never trust randomness on stage.

byllm_functions:
obj DonorProfile { has name: str; has blood: str; has hospital: str; has age: int; has note_excerpt: str; }
"""Extract the altruistic kidney donor's structured profile from this messy clinical referral email."""
def parse_intake(referral_note: str) -> DonorProfile by llm();

obj Case { has hospital: str; has backed_chain_id: str; has argument: str; has priority_score: int; }
"""You are the transplant advocate for one hospital. Given the proposed chains touching your patients, argue for the chain that best serves them, citing urgency and wait time."""
def plead(my_hospital: str, my_patients: list[str], chain_summaries: list[str], policy: str) -> Case by llm();

obj Ruling { has approved_chain_ids: list[str]; has rejected_chain_ids: list[str]; has rationale: str; }
"""You are the allocation arbiter. Chains sharing any pair conflict and cannot both proceed. Apply the written policy to the advocates' cases and select a maximal non-overlapping set."""
def arbitrate(cases: list[Case], conflict_map: str, policy: str) -> Ruling by llm();  // output is VALIDATED in Jac: if the LLM's set overlaps, fall back to greedy max-lives disjoint selection and log it
